#include <vector>
#include <string>
#include <unordered_map>

using namespace std;

class Solution {
public:
    vector<string> getFolderNames(vector<string>& names) {
        unordered_map<string, int> mp;
        vector<string> res;
        for (auto& name : names) {
            if (mp.count(name) == 0) {
                res.push_back(name);
                mp[name] = 1;
            } else {
                int k = mp[name];
                string newName;
                while (mp.count(newName = name + "(" + to_string(k) + ")")) {
                    ++k;
                }
                res.push_back(newName);
                mp[name] = k + 1;
                mp[newName] = 1;
            }
        }
        return res;
    }
};
